WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_d_done_to_total'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '已完求总量', 'kp-eng-d-done-to-total', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "已知部分求总量"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目给出某人做了几天后完成了【具体多少个零件/多少米】，反推整个工程的总量。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是前面所有比例和赋值法的破局点。特征是出现了真实的绝对数量，如“甲加工了 500 个零件”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "特值法只能算出“相对的份数”。只要用【真实的绝对数量 ÷ 对应的相对份数】，就能得到【每份代表多少真实量】。"}]}, {"type": "katexBlock", "attrs": {"content": "W_{真实总量} = W_{虚拟份数} \\times \\frac{\\text{真实数量}}{\\text{该部分对应的虚拟份数}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[先完全忽略绝对数量, 把题目当成纯比例题做] --> B[利用时间求出虚拟的 W份数 和 P份数]\nB --> C[根据题干计算出那个被给出绝对数量的人/阶段, 完成了多少 虚拟份数]\nC --> D[真实数量 ÷ 虚拟份数 = 换算系数 (1份等于几个)]\nD --> E[用 虚拟总 W份数 × 换算系数 = 真实的总工作量]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲独做 10 天，乙独做 15 天。两人合作，完工时甲比乙多做了 300 个零件。求这批零件共多少个？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "虚拟推演：令 W=30份。P甲=3份/天，P乙=2份/天。P合=5份/天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "合作时间：T = 30 ÷ 5 = 6 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算甲乙份数差：合作 6 天里，甲做了 6×3=18份，乙做了 6×2=12份。甲比乙多做了 18-12 = 6份。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "建立桥梁：这 6份 对应真实的 300 个零件！说明 1份 = 300 ÷ 6 = 50 个零件。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算真实总量：虚拟总量是 30份。真实总量 = 30 × 50 = 1500 个。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一上来就设总量为 X 列大方程：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "带绝对数量的题确实可以设 X，但这种“先当成全虚拟做，最后用系数放大”的【份数映射法】速度是方程法的 3 倍，且绝对不会错。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把相对值和绝对值的桥梁“换算系数 k”练成条件反射。"}]}]}$$ AS jsonb), NULL, '已完求总量的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "已完求总量"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_d_done_to_total", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
